      headers: {
        'Authorization': `Token ${emspCredentials.token}`,
        'Content-Type': 'application/json',
        'User-Agent': `${process.env.OCPI_PARTY_ID || 'IPD'}-CPO-OCPI-${process.env.OCPI_VERSION || '2.2'}`
