        timestamp: new Date().toISOString()
      });
    }

    // Validar que roles sea un array y no esté vacío
    if (!Array.isArray(roles) || roles.length === 0) {
      return res.status(400).json({
        status_code: 2001,
        status_message: 'Roles must be a non-empty array',
        timestamp: new Date().toISOString()
      });
