/* eslint-disable max-lines -- Archivo contiene múltiples funciones para obtener datos externos que requieren muchas líneas */
const { sequelize } = require('../../database/connection');
const { authMiddleware } = require('../../middleware/auth');
const EmspSession = require('../../models/EmspSession')(sequelize);

/**
 * Módulo para obtener datos externos de organizaciones conectadas
 */

/**
 * GET /get-external-sessions - Obtener y guardar sesiones de organizaciones externas conectadas
 */
// eslint-disable-next-line max-lines-per-function
function setupGetExternalSessions(router) {
  // eslint-disable-next-line max-lines-per-function, max-statements -- Función compleja que procesa múltiples organizaciones y sesiones
  router.get('/get-external-sessions', authMiddleware, async (_req, res) => {
    try {
      logger.info('🌐 Obteniendo y guardando sesiones de organizaciones externas conectadas...');

      // Obtener todas las organizaciones configuradas (excluyendo nuestro CPO)
      const organizations = await sequelize.query(`
            SELECT id, token, url, party_id, country_code, business_details
            FROM credentials 
            WHERE url IS NOT NULL 
            AND token IS NOT NULL
            AND url != ''
            AND token != ''
            AND party_id != 'IPD'
        `, {
        type: sequelize.QueryTypes.SELECT
      });

      if (organizations.length === 0) {
        return res.status(200).json({
          status_code: 1000,
          data: [],
          message: 'No hay organizaciones externas conectadas',
          timestamp: new Date().toISOString()
        });
      }

      logger.info(`📤 Consultando sesiones a ${organizations.length} organización(es) externa(s)`);

      const allSessions = [];
      const errors = [];
      let savedSessionsCount = 0;
      let duplicateSessionsCount = 0;

      // Consultar sesiones de cada organización
      // eslint-disable-next-line no-await-in-loop -- Necesario procesar organizaciones secuencialmente para evitar sobrecarga
      for (const org of organizations) {
        try {
          logger.info(`🔍 Consultando sesiones de ${org.party_id} (${org.url})`);

          // Construir URL para obtener sesiones del CPO externo
          const sessionsUrl = `${org.url}/ocpi/cpo/2.2/sessions`;

          // eslint-disable-next-line no-await-in-loop -- Necesario esperar respuesta antes de continuar
          const response = await fetch(sessionsUrl, {
            method: 'GET',
            headers: {
              'Authorization': `Token ${org.token}`,
              'Content-Type': 'application/json'
            }
          });

          // eslint-disable-next-line max-depth -- Anidación necesaria para validar respuesta y procesar datos
          if (response.ok) {
            // eslint-disable-next-line no-await-in-loop -- Necesario parsear respuesta antes de continuar
            const data = await response.json();
            // eslint-disable-next-line max-depth -- Anidación necesaria para validar estructura de datos
            if (data.data && Array.isArray(data.data)) {
              logger.info(`📥 Procesando ${data.data.length} sesiones de ${org.party_id}`);

              // Procesar cada sesión
              // eslint-disable-next-line no-await-in-loop -- Necesario procesar sesiones secuencialmente para evitar sobrecarga
              // eslint-disable-next-line max-depth -- Anidación necesaria para procesar cada sesión individualmente
              for (const session of data.data) {
                // eslint-disable-next-line max-depth -- Anidación necesaria para manejo de errores específicos
                try {
                  // Agregar información de la organización a la sesión
                  const sessionWithOrg = {
                    ...session,
                    // eslint-disable-next-line camelcase -- Campo requerido por la estructura de datos
                    source_organization: {
                      party_id: org.party_id,
                      country_code: org.country_code,
                      url: org.url,
                      business_details: org.business_details
                    }
                  };

                  allSessions.push(sessionWithOrg);

                  // Preparar datos para guardar en base de datos
                  const sessionData = {
                    emsp_party_id: org.party_id,
                    emsp_country_code: org.country_code,
                    country_code: session.country_code || org.country_code,
                    party_id: session.party_id || org.party_id,
                    session_id: session.id,
                    start_date_time: session.start_date_time ? new Date(session.start_date_time) : null,
                    end_date_time: session.end_date_time ? new Date(session.end_date_time) : null,
                    start_datetime: session.start_date_time ? new Date(session.start_date_time) : new Date(),
                    end_datetime: session.end_date_time ? new Date(session.end_date_time) : null,
                    kwh: session.kwh || 0.0,
                    cdr_token: session.auth_id ? {
                      uid: session.auth_id.uid,
                      type: session.auth_id.type,
                      issuer: session.auth_id.issuer
                    } : null,
                    id_token: session.auth_id?.uid || session.id || 'unknown',
                    auth_method: session.auth_method || 'RFID',
                    location_id: session.location_id || null,
                    evse_uid: session.evse_uid || session.location_id || 'unknown',
                    connector_id: session.connector_id || null,
                    currency: session.currency || 'EUR',
                    status: session.status || 'PENDING',
                    last_updated: session.last_updated ? new Date(session.last_updated) : new Date(),
                    total_cost: typeof session.total_cost === 'number' ? session.total_cost : (session.total_cost?.excl_vat ?? null),
                    charging_periods: session.charging_periods || null
                  };

                  // Intentar guardar en base de datos
                  // eslint-disable-next-line max-depth -- Anidación necesaria para manejo de errores específicos
                  try {
                    // eslint-disable-next-line no-await-in-loop -- Necesario guardar cada sesión antes de continuar
                    await EmspSession.create(sessionData);
                    savedSessionsCount++;
                    logger.info(`✅ Sesión ${session.id} guardada exitosamente`);
                  } catch (dbError) {
                    // eslint-disable-next-line max-depth -- Anidación necesaria para manejar diferentes tipos de errores
                    if (dbError.name === 'SequelizeUniqueConstraintError') {
                      duplicateSessionsCount++;
                      logger.info(`⚠️ Sesión ${session.id} ya existe, saltando...`);
                    } else {
                      // eslint-disable-next-line max-depth -- Anidación necesaria para manejo de errores específicos
                      logger.error(`❌ Error guardando sesión ${session.id}:`, dbError.message);
                      errors.push(`Error guardando sesión ${session.id}: ${dbError.message}`);
                    }
                  }
                } catch (sessionError) {
                  logger.error(`❌ Error procesando sesión:`, sessionError);
                  errors.push(`Error procesando sesión: ${sessionError.message}`);
                }
              }

              logger.info(`✅ ${data.data.length} sesiones procesadas de ${org.party_id}`);
            } else {
              logger.info(`⚠️ No se encontraron sesiones en ${org.party_id}`);
            }
          } else {
            // eslint-disable-next-line no-await-in-loop -- Necesario leer respuesta antes de continuar
            const errorText = await response.text();
            const error = `Error consultando ${org.party_id}: HTTP ${response.status} - ${errorText}`;
            errors.push(error);
            logger.warn(`⚠️ ${error}`);
          }
        } catch (orgError) {
          const error = `Error consultando ${org.party_id}: ${orgError.message}`;
          errors.push(error);
          logger.error(`❌ ${error}`);
        }
      }

      logger.info(`✅ Total de sesiones obtenidas: ${allSessions.length}`);
      logger.info(`💾 Sesiones guardadas en BD: ${savedSessionsCount}`);
      logger.info(`⚠️ Sesiones duplicadas (saltadas): ${duplicateSessionsCount}`);
      if (errors.length > 0) {
        logger.info(`❌ Errores encontrados: ${errors.length}`);
      }

      res.status(200).json({
        status_code: 1000,
        data: allSessions,
        metadata: {
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          total_sessions: allSessions.length,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          organizations_consulted: organizations.length,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          sessions_saved: savedSessionsCount,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          sessions_duplicates: duplicateSessionsCount,
          errors,
          timestamp: new Date().toISOString()
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('❌ Error obteniendo sesiones de organizaciones externas:', error);
      res.status(500).json({
        status_code: 2000,
        status_message: 'Error getting external sessions',
        timestamp: new Date().toISOString()
      });
    }
  });
}

