}

/**
 * GET /get-external-tokens - Obtener y guardar tokens de organizaciones externas conectadas
 */
function setupGetExternalTokens(router) {
  router.get('/get-external-tokens', authMiddleware, async (_req, res) => {
    try {
      logger.info('🌐 Obteniendo y guardando tokens de organizaciones externas conectadas...');

      const organizations = await sequelize.query(`
            SELECT id, token, url, party_id, country_code, business_details
            FROM credentials
            WHERE url IS NOT NULL
            AND token IS NOT NULL
            AND url != ''
            AND token != ''
            AND party_id != 'IPD'
        `, {
        type: sequelize.QueryTypes.SELECT
      });

      if (organizations.length === 0) {
        return res.status(200).json({
          status_code: 1000,
          data: [],
          message: 'No hay organizaciones externas conectadas',
          timestamp: new Date().toISOString()
        });
      }

      const allTokens = [];
      const errors = [];
      let savedTokensCount = 0;
      let duplicateTokensCount = 0;

      for (const org of organizations) {
        try {
          logger.info(`🔍 Consultando tokens de ${org.party_id} (${org.url})`);

          const tokensUrl = `${org.url}/ocpi/emsp/2.2/tokens`;

          const response = await fetch(tokensUrl, {
            method: 'GET',
            headers: {
              'Authorization': `Token ${org.token}`,
              'Content-Type': 'application/json'
            }
          });

          if (response.ok) {
            const data = await response.json();
            if (data.data && Array.isArray(data.data)) {
              logger.info(`📥 Procesando ${data.data.length} tokens de ${org.party_id}`);

              for (const token of data.data) {
                try {
                  allTokens.push({
                    ...token,
                    // eslint-disable-next-line camelcase -- Campo requerido por la estructura de datos
                    source_organization: {
                      party_id: org.party_id,
                      country_code: org.country_code,
                      url: org.url
                    }
                  });

                  const [result] = await sequelize.query(`
                                    INSERT INTO emsp_tokens (
                                        id, emsp_party_id, emsp_country_code, token_uid, type,
                                        contract_id, issuer, valid, whitelist, last_updated
                                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                                    ON CONFLICT (id) DO UPDATE SET
                                        valid = EXCLUDED.valid,
                                        whitelist = EXCLUDED.whitelist,
                                        last_updated = EXCLUDED.last_updated,
                                        updated_at = NOW()
                                `, {
                    replacements: [
                      token.uid,
                      org.party_id,
                      org.country_code,
                      token.uid,
                      token.type || 'RFID',
                      token.contract_id || null,
                      token.issuer || 'Unknown',
                      token.valid !== undefined ? token.valid : true,
                      token.whitelist || 'ALLOWED',
                      token.last_updated || new Date().toISOString()
                    ]
                  });

                  if (result.rowCount > 0) {
                    savedTokensCount++;
                  } else {
                    duplicateTokensCount++;
                  }
                } catch (tokenError) {
                  logger.error(`❌ Error procesando token:`, tokenError);
                  errors.push(`Error procesando token: ${tokenError.message}`);
                }
              }
            }
          } else {
            const errorText = await response.text();
            errors.push(`Error consultando ${org.party_id}: HTTP ${response.status} - ${errorText}`);
          }
        } catch (orgError) {
          errors.push(`Error consultando ${org.party_id}: ${orgError.message}`);
        }
      }

      res.status(200).json({
        status_code: 1000,
        data: allTokens,
        metadata: {
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          total_tokens: allTokens.length,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          organizations_consulted: organizations.length,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          tokens_saved: savedTokensCount,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          tokens_duplicates: duplicateTokensCount,
          errors,
          timestamp: new Date().toISOString()
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('❌ Error obteniendo tokens de organizaciones externas:', error);
      res.status(500).json({
        status_code: 2000,
        status_message: 'Error getting external tokens',
        timestamp: new Date().toISOString()
      });
    }
  });
}

