      let savedCount = 0;
      const errors = [];

      for (const location of locations) {
        try {
          // Validar campos obligatorios
          if (!location.party_id || !location.country_code || !location.id) {
            logger.warn(`⚠️ Location ${location.id} sin campos obligatorios, saltando...`);
            continue;
