                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT (id) 
                    DO UPDATE SET
                        emsp_party_id = EXCLUDED.emsp_party_id,
                        emsp_country_code = EXCLUDED.emsp_country_code,
                        location_id = EXCLUDED.location_id,
                        name = EXCLUDED.name,
