                        opening_times = EXCLUDED.opening_times,
                        charging_when_closed = EXCLUDED.charging_when_closed,
                        images = EXCLUDED.images,
                        energy_mix = EXCLUDED.energy_mix,
                        last_updated = EXCLUDED.last_updated,
