/**
 * POST /save-cpo-tariffs - Guardar tariffs de un CPO externo
 */
function setupSaveCpoTariffs(router) {
  router.post('/save-cpo-tariffs', authMiddleware, async (req, res) => {
    try {
      const { tariffs } = req.body;

      if (!tariffs || !Array.isArray(tariffs)) {
        return res.status(400).json({
          status_code: 2000,
          status_message: 'Missing required fields: tariffs array',
          timestamp: new Date().toISOString()
        });
      }

      logger.info(`🌐 Guardando ${tariffs.length} tariffs del CPO externo`);

      let savedCount = 0;
      const errors = [];

      // eslint-disable-next-line no-await-in-loop -- Necesario guardar cada tariff antes de continuar
      // eslint-disable-next-line max-depth -- Anidación necesaria para manejo de errores específicos
      for (const tariff of tariffs) {
        try {
          // Validar campos obligatorios
          // eslint-disable-next-line max-depth -- Anidación necesaria para validación condicional
          if (!tariff.party_id || !tariff.country_code || !tariff.id) {
            logger.warn(`⚠️ Tariff sin campos obligatorios party_id/country_code/id, saltando...`);
            continue;
          }

          const extractName = (altText, fallbackName) => {
            // eslint-disable-next-line max-depth -- Anidación necesaria para múltiples validaciones condicionales
            if (fallbackName && typeof fallbackName === 'string' && fallbackName.trim().length > 0) {
              return fallbackName;
            }

            if (!altText) {
              return null;
            }

            // eslint-disable-next-line max-depth -- Anidación necesaria para validación de tipo
            if (typeof altText === 'string') {
              return altText;
            }

            // eslint-disable-next-line max-depth -- Anidación necesaria para procesar arrays
            if (Array.isArray(altText)) {
              const entry = altText.find(item => item && typeof item.text === 'string' && item.text.trim().length > 0);
              return entry ? entry.text : null;
            }

            // eslint-disable-next-line max-depth -- Anidación necesaria para validación de objeto
            if (typeof altText === 'object' && typeof altText.text === 'string') {
              return altText.text;
            }

            return null;
          };

          const tariffName = extractName(tariff.tariff_alt_text, tariff.name);

          // Preparar valores con validación y valores por defecto
          const values = [
            tariff.id,
            tariff.party_id,
            tariff.country_code,
            tariff.id, // tariff_id es el mismo que id
            tariff.currency || 'EUR',
            tariff.type || 'REGULAR', // Campo obligatorio type
            tariffName,
            JSON.stringify(tariff.elements || []),
            tariff.start_date_time || null,
            tariff.end_date_time || null,
            tariff.last_updated || new Date().toISOString()
          ];

          logger.info(`🔍 Procesando tariff: ${tariff.id} (${tariff.party_id}_${tariff.country_code})`);

          // Insertar o actualizar tariff
          // eslint-disable-next-line no-await-in-loop -- Necesario guardar cada tariff antes de continuar
          await sequelize.query(`
                    INSERT INTO emsp_tariffs (
                        id, emsp_party_id, emsp_country_code, tariff_id, currency, type, 
                        name, elements, start_date_time, end_date_time, last_updated, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW())
                    ON CONFLICT (id) 
                    DO UPDATE SET
                        emsp_party_id = EXCLUDED.emsp_party_id,
                        emsp_country_code = EXCLUDED.emsp_country_code,
                        tariff_id = EXCLUDED.tariff_id,
                        currency = EXCLUDED.currency,
                        type = EXCLUDED.type,
                        name = EXCLUDED.name,
                        elements = EXCLUDED.elements,
                        start_date_time = EXCLUDED.start_date_time,
                        end_date_time = EXCLUDED.end_date_time,
                        last_updated = EXCLUDED.last_updated,
                        updated_at = NOW()
                `, {
            replacements: values
          });

          savedCount++;
          logger.info(`✅ Tariff ${tariff.id} guardado exitosamente`);
        } catch (tariffError) {
          logger.error(`❌ Error guardando tariff ${tariff.id}:`, tariffError);
          errors.push(`Tariff ${tariff.id}: ${tariffError.message}`);
        }
      }

      logger.info(`✅ ${savedCount} tariffs guardados exitosamente en emsp_tariffs`);

      res.status(200).json({
        status_code: 1000,
        data: {
          message: `${savedCount} tariffs guardados exitosamente`,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          total_received: tariffs.length,
          // eslint-disable-next-line camelcase -- Campos en snake_case según convención de API
          saved_count: savedCount,
          errors: errors.length > 0 ? errors : null
        },
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      logger.error('❌ Error guardando tariffs del CPO:', error);
      res.status(500).json({
        status_code: 2000,
        status_message: 'Error saving CPO tariffs',
        timestamp: new Date().toISOString()
      });
    }
  });
}

