        await sequelize.query(`
            UPDATE emsp_tariffs SET ${updateFields.join(', ')} WHERE id = ?
        `, { replacements });

        logger.info(`✅ Tariff patched: ${tariff_id}`, {
            updatedFields: Object.keys(updateData)
        });

