/**
 * Construye un snapshot del estado de los servicios combinando los datos almacenados con el estado runtime real
 */
const buildServicesStatusSnapshot = () => {
  const servicesSnapshot = {};

  // Copiar estado almacenado
  Object.entries(serviceStatus).forEach(([serviceKey, statusValue]) => {
    servicesSnapshot[serviceKey] = { ...statusValue };
  });

  // Mezclar con estado runtime real
  Object.entries(SERVICE_EXECUTOR_CONFIG).forEach(([serviceKey, config]) => {
    const resolver = SERVICE_RESOLVERS[serviceKey];
    if (!resolver) {
      return;
    }

    const serviceInstance = resolver();
    const runtimeStatus = getRuntimeServiceStatus(serviceInstance, config.inactiveStatus);

    servicesSnapshot[serviceKey] = {
      ...(servicesSnapshot[serviceKey] || {}),
      status: runtimeStatus.status
    };
  });

  return servicesSnapshot;
};

/**
 * Ejecuta una tarea de servicio individual y devuelve la información de resultado
 * @param {string} serviceKey
 */
const executeServiceJobOnce = async (serviceKey) => {
  const config = SERVICE_EXECUTOR_CONFIG[serviceKey];
  if (!config) {
    const error = new Error(`Servicio no soportado: ${serviceKey}`);
    error.statusCode = 400;
    throw error;
  }

  logger.info(`▶️ Ejecutando job manual: ${config.label}`);
  await config.run();
  logger.info(`✅ Job manual completado: ${config.label}`);

  const servicesSnapshot = buildServicesStatusSnapshot();
  return {
    jobName: config.label,
    services: servicesSnapshot
  };
};

/**
 * Alterna la ejecución continua de un servicio (start/stop)
 * @param {string} serviceKey
 */
const toggleServiceExecution = async (serviceKey) => {
  const config = SERVICE_EXECUTOR_CONFIG[serviceKey];
  if (!config) {
    const error = new Error(`Servicio no soportado: ${serviceKey}`);
    error.statusCode = 400;
    throw error;
  }

  const resolver = SERVICE_RESOLVERS[serviceKey];
  if (!resolver) {
    const error = new Error(`Resolver no definido para el servicio: ${serviceKey}`);
    error.statusCode = 500;
    throw error;
  }

  const serviceInstance = resolver();
  const runtimeStatus = getRuntimeServiceStatus(serviceInstance, config.inactiveStatus);
  const isCurrentlyActive = runtimeStatus.status === 'active';

  if (!serviceStatus[serviceKey]) {
    serviceStatus[serviceKey] = {
      status: config.inactiveStatus,
      lastRun: null,
      errorCount: 0
    };
  }

  let isActiveAfterToggle;
  let message;

  if (isCurrentlyActive) {
    await config.stop();
    serviceStatus[serviceKey].status = config.inactiveStatus;
    message = `${config.label} desactivado`;
    isActiveAfterToggle = false;
  } else {
    await config.start();
    serviceStatus[serviceKey].status = 'active';
    message = `${config.label} activado`;
    isActiveAfterToggle = true;
  }

  const servicesSnapshot = buildServicesStatusSnapshot();

  return {
    isActive: isActiveAfterToggle,
    status: servicesSnapshot[serviceKey]?.status || serviceStatus[serviceKey].status,
    message,
    services: servicesSnapshot
  };
};

module.exports = {
  SERVICE_RESOLVERS,
  SERVICE_EXECUTOR_CONFIG,
  getRuntimeServiceStatus,
  buildServicesStatusSnapshot,
  executeServiceJobOnce,
  toggleServiceExecution
};

const express = require('express');
const router = express.Router();
const { v4: uuidv4 } = require('uuid');

const { Token, EmspToken } = require('../models');
const logger = require('../utils/logger');
const { validateTokenPutMiddleware, validateTokenPatchMiddleware } = require('../validators/tokenValidators');

/**
 * Mapea un token de la base de datos al formato OCPI 2.2
 * @param {Object} token - Token de la base de datos
 * @returns {Object} Token mapeado según especificación OCPI 2.2
 */
function mapTokenToOCPI(token) {
  const mappedToken = {
    country_code: token.country_code,
    party_id: token.party_id,
    uid: token.uid,
    type: token.type,
    contract_id: token.contract_id,
    issuer: token.issuer,
    valid: token.valid,
    whitelist: token.whitelist,
    last_updated: token.last_updated.toISOString()
  };

  // Agregar campos opcionales si existen
  if (token.visual_number) {
    mappedToken.visual_number = token.visual_number;
  }
  
  if (token.group_id) {
    mappedToken.group_id = token.group_id;
  }
  
  if (token.language) {
    mappedToken.language = token.language;
  }
  
  if (token.default_profile_type) {
    mappedToken.default_profile_type = token.default_profile_type;
  }
  
  if (token.energy_contract) {
    mappedToken.energy_contract = token.energy_contract;
  }

  return mappedToken;
}

/**
 * @swagger
 * /ocpi/2.2/tokens:
 *   get:
 *     summary: Get OCPI tokens
 *     tags: [Tokens]
 *     parameters:
 *       - in: query
 *         name: country_code
 *         schema:
 *           type: string
 *       - in: query
 *         name: party_id
 *         schema:
 *           type: string
 *       - in: query
 *         name: type
 *         schema:
 *           type: string
 *       - in: query
 *         name: valid
 *         schema:
 *           type: boolean
 */
router.get('/', async (req, res) => {
  try {
    logger.ocpi('/tokens', 'GET', { query: req.query });
    
    const { country_code, party_id, type, valid, offset = 0, limit = 100 } = req.query;
    
    const where = {};
    if (country_code) where.country_code = country_code;
    if (party_id) where.party_id = party_id;
    if (type) where.type = type;
    if (valid !== undefined) where.valid = valid === 'true';
    
    const tokens = await Token.findAndCountAll({
      where,
      offset: parseInt(offset),
      limit: Math.min(parseInt(limit), 1000),
      order: [['last_updated', 'DESC']]
    });

    // Mapear tokens según especificación OCPI 2.2
    const mappedTokens = tokens.rows.map(mapTokenToOCPI);

    res.status(200).json({
      status_code: 1000,
      data: mappedTokens,
      timestamp: new Date().toISOString(),
      pagination: {
        total: tokens.count,
        offset: parseInt(offset),
        limit: Math.min(parseInt(limit), 1000)
      }
    });
  } catch (error) {
    logger.error('Error getting tokens:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /ocpi/2.2/tokens/{id}:
 *   get:
 *     summary: Get specific OCPI token
 *     tags: [Tokens]
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 */
router.get('/:id', async (req, res) => {
  try {
    logger.ocpi('/tokens', 'GET_BY_ID', { id: req.params.id });
    
    const { id } = req.params;
    const token = await Token.findByPk(id);
    
    if (!token) {
      return res.status(404).json({
        status_code: 2004,
        status_message: 'Token not found',
        timestamp: new Date().toISOString()
      });
    }

    // Mapear token según especificación OCPI 2.2
    const mappedToken = mapTokenToOCPI(token);

    res.status(200).json({
      status_code: 1000,
      data: mappedToken,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error getting token:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /ocpi/2.2/tokens:
 *   post:
 *     summary: Create new OCPI token
 *     tags: [Tokens]
 */
router.post('/', async (req, res) => {
  try {
    logger.ocpi('/tokens', 'POST', { body: req.body });
    
    const tokenData = {
      id: uuidv4(),
      ...req.body,
      party_id: process.env.OCPI_PARTY_ID,
      country_code: process.env.OCPI_COUNTRY_CODE,
      last_updated: new Date()
    };

    const token = await Token.create(tokenData);

    // Notificar a operadores conectados sobre el nuevo token
    try {
      const emspNotificationService = require('../services/emspNotificationService');
      await emspNotificationService.notifyTokenCreated(token);
      logger.info(`📤 Notificación POST de token ${token.uid} enviada a operadores conectados`);
    } catch (notificationError) {
      logger.error('❌ Error notificando token a operadores:', notificationError);
      // No fallar la creación del token si falla la notificación
    }

    res.status(201).json({
      status_code: 1000,
      data: token,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error creating token:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /ocpi/2.2/tokens/{country_code}/{party_id}/{uid}:
 *   put:
 *     summary: Create or update OCPI token by country_code, party_id and uid
 *     tags: [Tokens]
 *     parameters:
 *       - in: path
 *         name: country_code
 *         required: true
 *         schema:
 *           type: string
 *       - in: path
 *         name: party_id
 *         required: true
 *         schema:
 *           type: string
 *       - in: path
 *         name: uid
 *         required: true
 *         schema:
 *           type: string
 */
router.put('/:country_code/:party_id/:uid', validateTokenPutMiddleware, async (req, res) => {
  try {
    const { country_code, party_id, uid } = req.params;
    const tokenData = req.validatedToken; // Use validated data from middleware

    logger.ocpi('/tokens', 'PUT', {
      country_code,
      party_id,
      uid,
      body: tokenData
    });

    // Buscar token existente o crear uno nuevo en emsp_tokens
    let token = await EmspToken.findOne({
      where: {
        emsp_country_code: country_code,
        emsp_party_id: party_id,
        token_uid: uid
      }
    });

    if (token) {
      // Actualizar token existente
      await token.update({
        type: tokenData.type,
        contract_id: tokenData.contract_id || `${country_code}-${party_id}-${uid}`,
        issuer: tokenData.issuer,
        valid: tokenData.valid !== undefined ? tokenData.valid : true,
        whitelist: tokenData.whitelist || 'NEVER',
        language: tokenData.language || null,
        default_profile_type: tokenData.default_profile_type || null,
        energy_contract: tokenData.energy_contract || null,
        last_updated: new Date()
      });
      logger.info(`EMSP Token ${uid} actualizado para ${party_id}_${country_code}`);
    } else {
      // Generar ID único para el nuevo token
      const tokenId = `${party_id}-${uid}`;
      
      // Crear nuevo token en emsp_tokens con mapeo correcto
      token = await EmspToken.create({
        id: tokenId,
        emsp_party_id: party_id,
        emsp_country_code: country_code,
        token_uid: uid,
        type: tokenData.type,
        contract_id: tokenData.contract_id || `${country_code}-${party_id}-${uid}`,
        issuer: tokenData.issuer,
        valid: tokenData.valid !== undefined ? tokenData.valid : true,
        whitelist: tokenData.whitelist || 'NEVER',
        language: tokenData.language || null,
        default_profile_type: tokenData.default_profile_type || null,
        energy_contract: tokenData.energy_contract || null,
        last_updated: new Date()
      });
      logger.info(`Nuevo EMSP Token ${uid} creado para ${party_id}_${country_code} con ID ${tokenId}`);
    }

    // Mapear respuesta según especificación OCPI 2.2 para EMSP tokens
    const mappedToken = {
      country_code: token.emsp_country_code,
      party_id: token.emsp_party_id,
      uid: token.token_uid,
      type: token.type,
      contract_id: token.contract_id,
      issuer: token.issuer,
      valid: token.valid,
      whitelist: token.whitelist,
      last_updated: token.last_updated.toISOString()
    };

    // Agregar campos opcionales si existen
    if (token.visual_number) {
      mappedToken.visual_number = token.visual_number;
    }
    
    if (token.group_id) {
      mappedToken.group_id = token.group_id;
    }
    
    if (token.language) {
      mappedToken.language = token.language;
    }
    
    if (token.default_profile_type) {
      mappedToken.default_profile_type = token.default_profile_type;
    }
    
    if (token.energy_contract) {
      mappedToken.energy_contract = token.energy_contract;
    }

    res.status(200).json({
      status_code: 1000,
      data: mappedToken,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error creating/updating token:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /ocpi/2.2/tokens/{country_code}/{party_id}/{uid}:
 *   patch:
 *     summary: Partially update OCPI token by country_code, party_id and uid
 *     tags: [Tokens]
 *     parameters:
 *       - in: path
 *         name: country_code
 *         required: true
 *         schema:
 *           type: string
 *       - in: path
 *         name: party_id
 *         required: true
 *         schema:
 *           type: string
 *       - in: path
 *         name: uid
 *         required: true
 *         schema:
 *           type: string
 */
router.patch('/:country_code/:party_id/:uid', validateTokenPatchMiddleware, async (req, res) => {
  try {
    const { country_code, party_id, uid } = req.params;
    const patchData = req.validatedTokenPatch; // Use validated data from middleware

    logger.ocpi('/tokens', 'PATCH', {
      country_code,
      party_id,
      uid,
      body: patchData
    });

    // Buscar token existente en emsp_tokens
    const token = await EmspToken.findOne({
      where: {
        emsp_country_code: country_code,
        emsp_party_id: party_id,
        token_uid: uid
      }
    });

    if (!token) {
      return res.status(404).json({
        status_code: 2003,
        status_message: `Token not found: ${country_code}/${party_id}/${uid}`,
        timestamp: new Date().toISOString()
      });
    }

    // Preparar datos para actualización (solo los campos enviados)
    const updateData = { ...patchData };

    // Siempre actualizar last_updated
    updateData.last_updated = new Date();

    // Actualizar solo los campos proporcionados
    await token.update(updateData);

    logger.info(`EMSP Token ${uid} parcialmente actualizado para ${party_id}_${country_code}`);

    // Mapear respuesta según especificación OCPI 2.2
    const mappedToken = {
      country_code: token.emsp_country_code,
      party_id: token.emsp_party_id,
      uid: token.token_uid,
      type: token.type,
      contract_id: token.contract_id,
      issuer: token.issuer,
      valid: token.valid,
      whitelist: token.whitelist,
      last_updated: token.last_updated.toISOString()
    };

    // Agregar campos opcionales si existen
    if (token.visual_number) {
      mappedToken.visual_number = token.visual_number;
    }

    if (token.group_id) {
      mappedToken.group_id = token.group_id;
    }

    if (token.language) {
      mappedToken.language = token.language;
    }

    if (token.default_profile_type) {
      mappedToken.default_profile_type = token.default_profile_type;
    }

    if (token.energy_contract) {
      mappedToken.energy_contract = token.energy_contract;
    }

    res.status(200).json({
