const OCPITokenService = require('../services/ocpiTokenService');
const logger = require('../utils/logger');

// Token OCPI por defecto para desarrollo (se usará solo si no hay tokens en BD)
const DEFAULT_OCPI_TOKEN = process.env.OCPI_TOKEN || 'ocpi_token_ipd_2024_secure_key';

/**
 * Middleware de autenticación OCPI
 * Valida que la petición incluya el token correcto en las cabeceras
 */
const authMiddleware = async (req, res, next) => {
  try {
    // Obtener el token de las cabeceras
    const authHeader = req.headers.authorization;
    const token = req.headers['ocpi-token'] || req.headers['OCPI-Token'];

    // Verificar si se proporcionó algún token
    if (!authHeader && !token) {
      logger.warn('Authentication failed: No token provided', { 
        ip: req.ip, 
        path: req.path,
        headers: req.headers 
      });

      return res.status(401).json({
        status_code: 2001,
        status_message: 'Authentication failed: No token provided',
        timestamp: new Date().toISOString()
      });
    }

    // Verificar el token en Authorization header (formato: "Token {token}")
    let providedToken = null;
    if (authHeader && authHeader.startsWith('Token ')) {
      providedToken = authHeader.substring(6); // Remover "Token " del inicio
    } else if (token) {
      providedToken = token;
    }

    // Validar el token usando el servicio OCPI
    const tokenInfo = await OCPITokenService.validateToken(providedToken);

    if (!tokenInfo) {
      // Si no se encuentra en BD, verificar el token por defecto (para compatibilidad)
      if (providedToken !== DEFAULT_OCPI_TOKEN) {
        logger.warn('Authentication failed: Invalid token', { 
          ip: req.ip, 
          path: req.path,
          providedToken: providedToken ? `${providedToken.substring(0, 10)  }...` : 'none'
        });

        return res.status(401).json({
          status_code: 2001,
          status_message: 'Authentication failed: Invalid token',
          timestamp: new Date().toISOString()
        });
      }
    } else {
      // Si el token es temporal, verificar si está permitido en este endpoint
      if (tokenInfo.temp === true) {
        // Endpoints que permiten tokens temporales (handshake)
        const tempTokenAllowedPaths = [
          '/ocpi/versions',
          '/ocpi/cpo/2.2/details', 
          '/ocpi/cpo/2.2/credentials'
        ];

        const isTempTokenAllowed = tempTokenAllowedPaths.some(path => 
          req.originalUrl.startsWith(path)
        );

        if (!isTempTokenAllowed) {
          logger.warn('Authentication failed: Temporary token not allowed for this endpoint', { 
            ip: req.ip, 
            path: req.path,
            providedToken: providedToken ? `${providedToken.substring(0, 10)  }...` : 'none'
          });

          return res.status(403).json({
            status_code: 2002,
            status_message: 'Forbidden: This endpoint requires a permanent token',
            timestamp: new Date().toISOString()
          });
        }
      }
    }

    // Token válido, agregar información del token a la request
    req.ocpiToken = tokenInfo || { 
      party_id: process.env.OCPI_PARTY_ID || 'IPD', 
      country_code: process.env.OCPI_COUNTRY_CODE || 'ES',
      type: 'default' 
    };

    logger.info('Authentication successful', { 
      ip: req.ip, 
      path: req.path,
      partyId: req.ocpiToken.party_id,
      countryCode: req.ocpiToken.country_code
    });

    next();
  } catch (error) {
    logger.error('Authentication error:', error);
    return res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error during authentication',
      timestamp: new Date().toISOString()
    });
  }
};

/**
 * Middleware opcional para endpoints que no requieren autenticación
 * (como health check, documentación, etc.)
 */
const optionalAuthMiddleware = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    const token = req.headers['ocpi-token'] || req.headers['OCPI-Token'];

    let providedToken = null;
    if (authHeader && authHeader.startsWith('Token ')) {
      providedToken = authHeader.substring(6);
    } else if (token) {
      providedToken = token;
    }

    // Si se proporciona un token, validarlo
    if (providedToken) {
      const tokenInfo = await OCPITokenService.validateToken(providedToken);

      if (!tokenInfo && providedToken !== DEFAULT_OCPI_TOKEN) {
        logger.warn('Optional authentication failed: Invalid token', { 
          ip: req.ip, 
          path: req.path 
        });

        return res.status(401).json({
          status_code: 2001,
          status_message: 'Authentication failed: Invalid token',
          timestamp: new Date().toISOString()
        });
      }

      // Si el token es válido, agregar información a la request
      if (tokenInfo) {
        req.ocpiToken = tokenInfo;
      }
    }

    // Continuar (con o sin token válido)
    next();
  } catch (error) {
    logger.error('Optional authentication error:', error);
    next(); // Continuar en caso de error
  }
};

module.exports = {
  authMiddleware,
  optionalAuthMiddleware,
  DEFAULT_OCPI_TOKEN
};

const { logApplicationError } = require('../utils/applicationErrorLogger');
const logger = require('../utils/logger');

const errorHandler = async (err, req, res, next) => {
  logger.error('Error occurred', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Log application error to database
  await logApplicationError({
    error_type: err.name || 'SERVER_ERROR',
    direction: 'INBOUND',
    endpoint: req.originalUrl || req.url,
    method: req.method,
    status_code: err.statusCode || 500,
    error_message: err.message || 'Internal Server Error',
    error_stack: err.stack || null,
    request_body: req.body || null,
    request_headers: req.headers || null,
    ip_address: req.ip || req.connection?.remoteAddress || null,
    user_agent: req.get('user-agent') || null
  });

  // OCPI 2.2 specific error responses
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status_code: 2001,
      status_message: 'Invalid or missing parameters',
      timestamp: new Date().toISOString()
    });
  }

  if (err.name === 'SequelizeValidationError') {
    return res.status(400).json({
      status_code: 2001,
      status_message: 'Invalid data format',
      timestamp: new Date().toISOString()
    });
  }

  if (err.name === 'SequelizeUniqueConstraintError') {
    return res.status(409).json({
      status_code: 2002,
      status_message: 'Resource already exists',
      timestamp: new Date().toISOString()
    });
  }

  if (err.name === 'SequelizeForeignKeyConstraintError') {
    return res.status(400).json({
      status_code: 2003,
      status_message: 'Referenced resource does not exist',
      timestamp: new Date().toISOString()
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  res.status(statusCode).json({
    status_code: statusCode,
    status_message: message,
    timestamp: new Date().toISOString()
  });
};

module.exports = errorHandler;

const logger = require('../utils/logger');

/**
 * Middleware para logging detallado de peticiones y respuestas
 * Captura payload entrante y response saliente
 */
const requestLogger = (req, res, next) => {
  // Excluir endpoints de logs para evitar bucles infinitos
  if (req.path === '/logs/recent' || req.path === '/logs/stream') {
    return next();
  }

  // Excluir peticiones del navegador (aplicación web)
  const userAgent = req.get('User-Agent') || '';
  if (userAgent.includes('Mozilla') || userAgent.includes('Chrome') || userAgent.includes('Safari')) {
    return next();
  }

  // Excluir recursos estáticos
  if (req.path.match(/\.(css|js|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$/)) {
    return next();
  }

  // Excluir health check
  if (req.path === '/health') {
    return next();
  }

  // Excluir peticiones de la interfaz web (API calls desde el frontend)
  if (req.path.startsWith('/api/') && userAgent.includes('Mozilla')) {
    return next();
  }

  // Capturar el tiempo de inicio
  const startTime = Date.now();

  // Capturar el body de la petición (si existe)
  let requestBody = null;
  if (req.body && Object.keys(req.body).length > 0) {
    requestBody = JSON.parse(JSON.stringify(req.body));
  }

  // Capturar headers relevantes
  const relevantHeaders = {
    'authorization': req.headers.authorization ? `${req.headers.authorization.substring(0, 20)}...` : undefined,
    'ocpi-token': req.headers['ocpi-token'] ? `${req.headers['ocpi-token'].substring(0, 20)}...` : undefined,
    'content-type': req.headers['content-type'],
    'user-agent': req.headers['user-agent'],
    'accept': req.headers.accept
  };

  // Filtrar headers undefined
  Object.keys(relevantHeaders).forEach(key => {
    if (relevantHeaders[key] === undefined) {
      delete relevantHeaders[key];
    }
  });

  // Log de la petición entrante
  logger.info('🚀 API Request Incoming', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    path: req.path,
    ip: req.ip,
    headers: relevantHeaders,
    query: Object.keys(req.query).length > 0 ? req.query : undefined,
    body: requestBody,
    userAgent: req.get('User-Agent')
  });

  // Interceptar la respuesta para capturar el body
  const originalSend = res.send;
  const originalJson = res.json;

  let responseBody = null;
  let responseHeaders = null;

  // Interceptar res.send()
  res.send = function(data) {
    responseBody = data;
    responseHeaders = res.getHeaders();
    return originalSend.call(this, data);
  };

  // Interceptar res.json()
  res.json = function(data) {
    responseBody = data;
    responseHeaders = res.getHeaders();
    return originalJson.call(this, data);
  };

  // Capturar cuando la respuesta se envía
  res.on('finish', async () => {
    const endTime = Date.now();
    const responseTime = endTime - startTime;

    // Log detallado de la petición completa
    logger.info(`🌐 ${req.method} ${req.path}`, {
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      path: req.path,
      statusCode: res.statusCode,
      statusMessage: res.statusMessage,
      responseTime: `${responseTime}ms`,
      requestHeaders: relevantHeaders,
      requestBody,
      responseHeaders,
      responseBody,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      query: Object.keys(req.query).length > 0 ? req.query : undefined
    });

    // Log application error if status code >= 400
    if (res.statusCode >= 400) {
      const { logApplicationError } = require('../utils/applicationErrorLogger');
      await logApplicationError({
        error_type: res.statusCode >= 500 ? 'SERVER_ERROR' : 'API_RESPONSE',
        direction: 'INBOUND',
        endpoint: req.originalUrl || req.url,
        method: req.method,
        status_code: res.statusCode,
        error_message: res.statusMessage || `HTTP ${res.statusCode}`,
        request_body: requestBody,
        response_body: responseBody,
        request_headers: relevantHeaders,
        response_headers: responseHeaders,
        ip_address: req.ip || req.connection?.remoteAddress || null,
        user_agent: req.get('user-agent') || null
      });
    }

    // Log resumido para debugging rápido (solo si no es una petición del navegador)
    const userAgent = req.get('User-Agent') || '';
    if (!userAgent.includes('Mozilla') && !userAgent.includes('Chrome') && !userAgent.includes('Safari')) {
      logger.info('📊 API Request Summary', {
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        responseTime: `${responseTime}ms`,
        requestSize: requestBody ? JSON.stringify(requestBody).length : 0,
        responseSize: responseBody ? JSON.stringify(responseBody).length : 0,
        ip: req.ip
      });
    }
  });

  next();
};

module.exports = requestLogger;

const { Credentials } = require('../models');
const logger = require('../utils/logger');

/**
 * Middleware de autenticación para tokens temporales
 * Solo permite acceso a endpoints básicos: /versions, /credentials, /details
 */
const tempTokenAuth = async (req, res, next) => {
    try {
        const authHeader = req.headers.authorization;

        if (!authHeader || !authHeader.startsWith('Token ')) {
            logger.warn('Temp token auth failed: No authorization header', {
                ip: req.ip,
                path: req.path,
                method: req.method
            });

            return res.status(401).json({
                status_code: 2001,
                status_message: 'Authentication failed: Missing token',
                timestamp: new Date().toISOString()
            });
        }

        const token = authHeader.substring(6); // Remove 'Token ' prefix

        // Buscar el token en la base de datos
        const credentials = await Credentials.findOne({
            where: {
                token,
                valid: true,
                temp: true
            }
        });

        if (!credentials) {
            logger.warn('Temp token auth failed: Invalid or expired token', {
                ip: req.ip,
                path: req.path,
                method: req.method,
                providedToken: `${token.substring(0, 10)  }...`
            });

            return res.status(401).json({
                status_code: 2001,
                status_message: 'Authentication failed: Invalid or expired token',
                timestamp: new Date().toISOString()
            });
        }

        // Verificar que el endpoint esté permitido para tokens temporales
        // Para /ocpi/versions, el path interno es '/' pero la URL original es '/ocpi/versions'
        const originalPath = req.originalUrl.split('?')[0];
        const isVersionsEndpoint = originalPath === '/ocpi/versions' || originalPath === '/ocpi/versions/';
        const isCredentialsEndpoint = originalPath.startsWith('/ocpi/cpo/2.2/credentials');
        const isDetailsEndpoint = originalPath.startsWith('/ocpi/cpo/2.2/details');

        const isAllowedPath = isVersionsEndpoint || isCredentialsEndpoint || isDetailsEndpoint;

        // Debug logging (comentado para producción)
        // console.log('🔍 Temp token auth - Original URL:', req.originalUrl);
        // console.log('🔍 Temp token auth - Path:', req.path);
        // console.log('🔍 Temp token auth - Original path:', originalPath);
        // console.log('🔍 Temp token auth - Is versions:', isVersionsEndpoint);
        // console.log('🔍 Temp token auth - Is credentials:', isCredentialsEndpoint);
        // console.log('🔍 Temp token auth - Is details:', isDetailsEndpoint);
        // console.log('🔍 Temp token auth - Is allowed:', isAllowedPath);

        if (!isAllowedPath) {
            logger.warn('Temp token auth failed: Endpoint not allowed for temporary tokens', {
                ip: req.ip,
                path: req.path,
                method: req.method,
                providedToken: `${token.substring(0, 10)  }...`
            });

            return res.status(403).json({
                status_code: 2002,
                status_message: 'Forbidden: This endpoint requires a permanent token',
                timestamp: new Date().toISOString()
            });
        }

        // Agregar información del token a la request
        req.credentials = credentials;
        req.tokenType = 'temp';

        logger.info('Temp token auth successful', {
            ip: req.ip,
            path: req.path,
            method: req.method,
            partyId: credentials.party_id,
            countryCode: credentials.country_code
        });

        next();
    } catch (error) {
        logger.error('Temp token auth error:', error);

        res.status(500).json({
            status_code: 2000,
            status_message: 'Internal server error during authentication',
            timestamp: new Date().toISOString()
        });
    }
};

module.exports = tempTokenAuth;

const { DataTypes } = require('sequelize');

const { sequelize } = require('../database/connection');

const ApplicationError = sequelize.define('ApplicationError', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true,
    allowNull: false
  },
  error_type: {
    type: DataTypes.STRING(50),
    allowNull: false,
    comment: 'Type of error: API_REQUEST, API_RESPONSE, SERVER_ERROR, etc.'
  },
  direction: {
    type: DataTypes.STRING(20),
    allowNull: false,
    comment: 'Direction: INBOUND (request received) or OUTBOUND (request sent)'
