     */
    async notifyOrganizationAboutEVSE(organization, evseData, method = 'PUT') {
        try {
            // Construir la URL correcta según OCPI 2.2: /ocpi/emsp/2.2/locations/{country_code}/{party_id}/{location_id}/{evse_uid}
