    test('should accept case-insensitive match for country_code', () => {
      const params = { country_code: 'es', party_id: 'ABC', uid: 'token-123' };
      const body = {
        country_code: 'ES',
        party_id: 'ABC',
        uid: 'token-123',
        type: 'RFID',
        contract_id: 'contract-123',
        issuer: 'Test Company',
        valid: true,
        whitelist: 'ALLOWED',
        last_updated: '2025-01-15T10:30:00Z'
      };

      const result = validateTokenPut(params, body);
      expect(result.valid).toBe(true);
    });

    test('should accept case-insensitive match for party_id', () => {
      const params = { country_code: 'ES', party_id: 'abc', uid: 'token-123' };
      const body = {
        country_code: 'ES',
        party_id: 'ABC',
        uid: 'token-123',
        type: 'RFID',
        contract_id: 'contract-123',
        issuer: 'Test Company',
        valid: true,
        whitelist: 'ALLOWED',
        last_updated: '2025-01-15T10:30:00Z'
      };

      const result = validateTokenPut(params, body);
      expect(result.valid).toBe(true);
    });
  });
});

