const Joi = require('joi');
const { ciString, dateTime, ocpiString } = require('../../utils/ocpiValidators');
const { PARKING_TYPES, FACILITIES } = require('./enums');
const {
  geoLocationSchema,
  additionalGeoLocationSchema,
  publishTokenTypeSchema,
  displayTextSchema,
  imageSchema,
  businessDetailsSchema
} = require('./basicSchemas');
const { hoursSchema } = require('./hoursSchemas');
const { evseSchema } = require('./evseSchemas');

/**
 * Esquemas relacionados con Location para validadores Location
 */

/**
 * Location PUT body validator (8.3.1)
 */
const locationPutBodySchema = Joi.object({
  country_code: ciString(2).required()
    .messages({
      'any.required': 'country_code is required',
      'string.max': 'country_code must be exactly 2 characters (ISO-3166 alpha-2)'
    }),

  party_id: ciString(3).required()
    .messages({
      'any.required': 'party_id is required',
      'string.max': 'party_id must be at most 3 characters (ISO-15118 standard)'
    }),

  id: ciString(36).required()
    .messages({
      'any.required': 'id is required',
      'string.max': 'id must be at most 36 characters'
    }),

  publish: Joi.boolean().required()
    .messages({
      'any.required': 'publish is required',
      'boolean.base': 'publish must be a boolean'
    }),

  publish_allowed_to: Joi.array()
    .items(publishTokenTypeSchema)
    .when('publish', {
      is: false,
      then: Joi.optional(),
      otherwise: Joi.forbidden()
    })
    .messages({
      'any.unknown': 'publish_allowed_to may only be used when publish is false'
    }),

  name: ocpiString(255).optional()
    .messages({
      'string.max': 'name must be at most 255 characters'
    }),

  address: ocpiString(45).required()
    .messages({
      'any.required': 'address is required',
      'string.max': 'address must be at most 45 characters'
    }),

  city: ocpiString(45).required()
    .messages({
      'any.required': 'city is required',
      'string.max': 'city must be at most 45 characters'
    }),

  postal_code: ocpiString(10).optional()
    .messages({
      'string.max': 'postal_code must be at most 10 characters'
    }),

  state: ocpiString(20).optional()
    .messages({
      'string.max': 'state must be at most 20 characters'
    }),

  country: Joi.string()
    .length(3)
    .uppercase()
    .required()
    .messages({
      'any.required': 'country is required',
      'string.length': 'country must be exactly 3 characters (ISO 3166-1 alpha-3)'
    }),

  coordinates: geoLocationSchema.required()
    .messages({
      'any.required': 'coordinates is required'
    }),

  related_locations: Joi.array()
    .items(additionalGeoLocationSchema)
    .optional(),

  parking_type: Joi.string()
    .valid(...PARKING_TYPES)
    .optional(),

  evses: Joi.array()
    .items(evseSchema)
    .optional(),

  directions: Joi.array()
    .items(displayTextSchema)
    .optional(),

  operator: businessDetailsSchema.optional(),

  suboperator: businessDetailsSchema.optional(),

  owner: businessDetailsSchema.optional(),

  facilities: Joi.array()
    .items(Joi.string().valid(...FACILITIES))
    .optional(),

  time_zone: ocpiString(255).required()
    .messages({
      'any.required': 'time_zone is required',
      'string.max': 'time_zone must be at most 255 characters (IANA tzdata TZ-value)'
    }),

  opening_times: hoursSchema.optional(),

  charging_when_closed: Joi.boolean().optional()
    .messages({
      'boolean.base': 'charging_when_closed must be a boolean'
    }),

  images: Joi.array()
    .items(imageSchema)
    .optional(),

  energy_mix: Joi.any().optional(), // EnergyMix from cdrValidators if needed

  last_updated: dateTime().required()
    .messages({
      'any.required': 'last_updated is required'
    })
}).messages({
  'object.base': 'Request body must be a valid JSON object'
});

/**
 * Location PATCH body validator (all fields optional except last_updated)
 */
const locationPatchBodySchema = Joi.object({
  country_code: ciString(2).optional(),
  party_id: ciString(3).optional(),
  id: ciString(36).optional(),
  publish: Joi.boolean().optional(),
  publish_allowed_to: Joi.array().items(publishTokenTypeSchema).optional(),
  name: ocpiString(255).optional(),
  address: ocpiString(45).optional(),
  city: ocpiString(45).optional(),
  postal_code: ocpiString(10).optional(),
  state: ocpiString(20).optional(),
  country: Joi.string().length(3).uppercase().optional(),
  coordinates: geoLocationSchema.optional(),
  related_locations: Joi.array().items(additionalGeoLocationSchema).optional(),
  parking_type: Joi.string().valid(...PARKING_TYPES).optional(),
  evses: Joi.array().items(evseSchema).optional(),
  directions: Joi.array().items(displayTextSchema).optional(),
  operator: businessDetailsSchema.optional(),
  suboperator: businessDetailsSchema.optional(),
  owner: businessDetailsSchema.optional(),
  facilities: Joi.array().items(Joi.string().valid(...FACILITIES)).optional(),
  time_zone: ocpiString(255).optional(),
  opening_times: hoursSchema.optional(),
  charging_when_closed: Joi.boolean().optional(),
  images: Joi.array().items(imageSchema).optional(),
  energy_mix: Joi.any().optional(),
  last_updated: dateTime().required()
    .messages({
      'any.required': 'last_updated is required even in PATCH requests'
    })
}).min(2)
  .messages({
    'object.min': 'PATCH request must include at least one field to update besides last_updated'
  });

/**
 * Path parameters validator for Location PUT/PATCH
 */
const locationPathSchema = Joi.object({
  country_code: ciString(2).required()
    .messages({
      'any.required': 'country_code path parameter is required'
    }),

  party_id: ciString(3).required()
    .messages({
      'any.required': 'party_id path parameter is required'
    }),

  location_id: ciString(36).required()
    .messages({
      'any.required': 'location_id path parameter is required'
    })
});

module.exports = {
  locationPutBodySchema,
  locationPatchBodySchema,
  locationPathSchema
};

const { locationPutBodySchema, locationPatchBodySchema, locationPathSchema } = require('./locationSchemas');

/**
 * Funciones de validación para Location
 */

/**
 * Validates Location PUT request
 */
function validateLocationPut(params, body) {
  const pathValidation = locationPathSchema.validate(params, {
    abortEarly: false,
    stripUnknown: false
  });

  if (pathValidation.error) {
    return {
      valid: false,
      errors: pathValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  const bodyValidation = locationPutBodySchema.validate(body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (bodyValidation.error) {
    return {
      valid: false,
      errors: bodyValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  const pathParams = pathValidation.value;
  const bodyData = bodyValidation.value;
  const matchErrors = [];

  if (pathParams.country_code.toUpperCase() !== bodyData.country_code.toUpperCase()) {
    matchErrors.push({
      field: 'country_code',
      message: `country_code in path (${pathParams.country_code}) does not match body (${bodyData.country_code})`,
      type: 'mismatch'
    });
  }

  if (pathParams.party_id.toUpperCase() !== bodyData.party_id.toUpperCase()) {
    matchErrors.push({
      field: 'party_id',
      message: `party_id in path (${pathParams.party_id}) does not match body (${bodyData.party_id})`,
      type: 'mismatch'
    });
  }

  if (pathParams.location_id.toUpperCase() !== bodyData.id.toUpperCase()) {
    matchErrors.push({
      field: 'id',
      message: `location_id in path (${pathParams.location_id}) does not match body id (${bodyData.id})`,
      type: 'mismatch'
    });
  }

  if (matchErrors.length > 0) {
    return {
      valid: false,
      errors: matchErrors,
      value: null
    };
  }

  return {
    valid: true,
    errors: [],
    value: bodyData
  };
}

/**
 * Express middleware for Location PUT validation
 */
async function validateLocationPutMiddleware(req, res, next) {
  const validation = validateLocationPut(req.params, req.body);

  if (!validation.valid) {
    const errorMessage = validation.errors
      .map(err => `${err.field}: ${err.message}`)
      .join('; ');

    const logger = require('../../utils/logger');
    logger.error('❌ Location PUT validation failed', {
      errors: validation.errors,
      body: req.body
    });

    // Log validation error to database
    const { logValidationError } = require('../../utils/validationErrorLogger');
    await logValidationError({
      endpoint: req.originalUrl || req.url,
      method: req.method,
      requestBody: req.body,
      validationErrors: validation.errors,
      req
    });

    return res.status(400).json({
      status_code: 2001,
      status_message: `Invalid Location data: ${errorMessage}`,
      timestamp: new Date().toISOString(),
      errors: validation.errors
    });
  }

  req.validatedLocation = validation.value;
  next();
}

/**
 * Validates Location PATCH request
 */
function validateLocationPatch(params, body) {
  const pathValidation = locationPathSchema.validate(params, {
    abortEarly: false,
    stripUnknown: false
  });

  if (pathValidation.error) {
    return {
      valid: false,
      errors: pathValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  const bodyValidation = locationPatchBodySchema.validate(body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (bodyValidation.error) {
    return {
      valid: false,
      errors: bodyValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  const pathParams = pathValidation.value;
  const bodyData = bodyValidation.value;
  const matchErrors = [];

  if (bodyData.country_code && pathParams.country_code.toUpperCase() !== bodyData.country_code.toUpperCase()) {
    matchErrors.push({
      field: 'country_code',
      message: `country_code in path (${pathParams.country_code}) does not match body (${bodyData.country_code})`,
      type: 'mismatch'
    });
  }

  if (bodyData.party_id && pathParams.party_id.toUpperCase() !== bodyData.party_id.toUpperCase()) {
    matchErrors.push({
      field: 'party_id',
      message: `party_id in path (${pathParams.party_id}) does not match body (${bodyData.party_id})`,
      type: 'mismatch'
    });
  }

  if (bodyData.id && pathParams.location_id.toUpperCase() !== bodyData.id.toUpperCase()) {
    matchErrors.push({
      field: 'id',
      message: `location_id in path (${pathParams.location_id}) does not match body id (${bodyData.id})`,
      type: 'mismatch'
    });
  }

  if (matchErrors.length > 0) {
    return {
      valid: false,
      errors: matchErrors,
      value: null
    };
  }

  return {
    valid: true,
    errors: [],
    value: bodyData
  };
}

/**
 * Express middleware for Location PATCH validation
 */
function validateLocationPatchMiddleware(req, res, next) {
  const validation = validateLocationPatch(req.params, req.body);

  if (!validation.valid) {
    const errorMessage = validation.errors
      .map(err => `${err.field}: ${err.message}`)
      .join('; ');

    const logger = require('../../utils/logger');
    logger.error('❌ Location PATCH validation failed', {
      errors: validation.errors,
      body: req.body
    });

    return res.status(400).json({
      status_code: 2001,
      status_message: `Invalid Location PATCH data: ${errorMessage}`,
      timestamp: new Date().toISOString(),
      errors: validation.errors
    });
  }

  req.validatedLocationPatch = validation.value;
  next();
}

module.exports = {
  validateLocationPut,
  validateLocationPutMiddleware,
  validateLocationPatch,
  validateLocationPatchMiddleware
};

const Joi = require('joi');

const { ciString, dateTime, ocpiString, ocpiNumber } = require('../utils/ocpiValidators');

/**
 * OCPI 2.2 Session Validators
 * According to OCPI 2.2 specification - Sessions Module
 */

// TokenType enum (from OCPI 2.2)
const TOKEN_TYPES = ['AD_HOC_USER', 'APP_USER', 'OTHER', 'RFID'];

// AuthMethod enum (10.4.1)
const AUTH_METHODS = ['AUTH_REQUEST', 'COMMAND', 'WHITELIST'];

// SessionStatus enum (9.4.3)
const SESSION_STATUSES = ['ACTIVE', 'COMPLETED', 'INVALID', 'PENDING'];

/**
 * CdrToken schema validator (10.4.5)
 * Simplified Token object for CDRs and Sessions
 */
const cdrTokenSchema = Joi.object({
  uid: ciString(36).required()
    .messages({
      'any.required': 'cdr_token.uid is required',
      'string.max': 'cdr_token.uid must be at most 36 characters'
    }),

  type: Joi.string()
    .valid(...TOKEN_TYPES)
    .required()
    .messages({
      'any.required': 'cdr_token.type is required'
    }),

  contract_id: ciString(36).required()
    .messages({
      'any.required': 'cdr_token.contract_id is required',
      'string.max': 'cdr_token.contract_id must be at most 36 characters'
    })
}).messages({
  'object.base': 'cdr_token must be a valid object'
});

/**
 * Price schema validator (16.5)
 */
const priceSchema = Joi.object({
  excl_vat: ocpiNumber().required()
    .messages({
      'any.required': 'total_cost.excl_vat is required',
      'number.base': 'total_cost.excl_vat must be a number'
    }),

  incl_vat: ocpiNumber().optional()
    .messages({
      'number.base': 'total_cost.incl_vat must be a number'
    })
}).messages({
  'object.base': 'total_cost must be a valid Price object'
});

/**
 * CdrDimension schema validator (10.4.4)
 */
const cdrDimensionSchema = Joi.object({
  type: Joi.string()
    .valid('CURRENT', 'ENERGY', 'ENERGY_EXPORT', 'ENERGY_IMPORT', 'MAX_CURRENT',
           'MIN_CURRENT', 'MAX_POWER', 'MIN_POWER', 'PARKING_TIME', 'POWER',
           'RESERVATION_TIME', 'STATE_OF_CHARGE', 'TIME')
    .required()
    .messages({
      'any.required': 'charging_period.dimension.type is required'
    }),

  volume: ocpiNumber().required()
    .messages({
      'any.required': 'charging_period.dimension.volume is required',
      'number.base': 'charging_period.dimension.volume must be a number'
    })
}).messages({
  'object.base': 'charging_period.dimension must be a valid object'
});

/**
 * ChargingPeriod schema validator (10.4.6)
 */
const chargingPeriodSchema = Joi.object({
  start_date_time: dateTime().required()
    .messages({
      'any.required': 'charging_period.start_date_time is required'
    }),

  dimensions: Joi.array()
    .items(cdrDimensionSchema)
    .min(1)
    .required()
    .messages({
      'any.required': 'charging_period.dimensions is required',
      'array.min': 'charging_period.dimensions must contain at least one dimension'
    }),

  tariff_id: ciString(36).optional()
    .messages({
      'string.max': 'charging_period.tariff_id must be at most 36 characters'
    })
}).messages({
  'object.base': 'charging_period must be a valid object'
});

/**
 * Session PUT body validator
 * Complete Session object according to OCPI 2.2 spec
 */
const sessionPutBodySchema = Joi.object({
  country_code: ciString(2).required()
    .messages({
      'any.required': 'country_code is required',
      'string.max': 'country_code must be exactly 2 characters (ISO-3166 alpha-2)'
    }),

  party_id: ciString(3).required()
    .messages({
      'any.required': 'party_id is required',
      'string.max': 'party_id must be at most 3 characters (ISO-15118 standard)'
    }),

  id: ciString(36).required()
    .messages({
      'any.required': 'id is required',
      'string.max': 'id must be at most 36 characters'
    }),

  start_date_time: dateTime().required()
    .messages({
      'any.required': 'start_date_time is required'
    }),

  end_date_time: dateTime().optional(),

  kwh: ocpiNumber().required()
    .messages({
      'any.required': 'kwh is required',
      'number.base': 'kwh must be a number'
    }),

  cdr_token: cdrTokenSchema.required()
    .messages({
      'any.required': 'cdr_token is required',
      'object.base': 'cdr_token must be a valid CdrToken object'
    }),

  auth_method: Joi.string()
    .valid(...AUTH_METHODS)
    .required()
    .messages({
      'any.required': 'auth_method is required'
    }),

  authorization_reference: ciString(36).optional()
    .messages({
      'string.max': 'authorization_reference must be at most 36 characters'
    }),

  location_id: ciString(36).required()
    .messages({
      'any.required': 'location_id is required',
      'string.max': 'location_id must be at most 36 characters'
    }),

  evse_uid: ciString(36).required()
    .messages({
      'any.required': 'evse_uid is required',
      'string.max': 'evse_uid must be at most 36 characters'
    }),

  connector_id: ciString(36).required()
    .messages({
      'any.required': 'connector_id is required',
      'string.max': 'connector_id must be at most 36 characters'
    }),

  meter_id: ocpiString(255).optional()
    .messages({
      'string.max': 'meter_id must be at most 255 characters'
    }),

  currency: Joi.string()
    .length(3)
    .uppercase()
    .required()
    .messages({
      'any.required': 'currency is required',
      'string.length': 'currency must be exactly 3 characters (ISO 4217 code)'
    }),

  charging_periods: Joi.array()
    .items(chargingPeriodSchema)
    .optional()
    .messages({
      'array.base': 'charging_periods must be an array'
    }),

  total_cost: priceSchema.optional(),

  status: Joi.string()
    .valid(...SESSION_STATUSES)
    .required()
    .messages({
      'any.required': 'status is required'
    }),

  last_updated: dateTime().required()
    .messages({
      'any.required': 'last_updated is required'
    })
}).messages({
  'object.base': 'Request body must be a valid JSON object'
});

/**
 * Path parameters validator for Session PUT
 */
const sessionPutPathSchema = Joi.object({
  country_code: ciString(2).required()
    .messages({
      'any.required': 'country_code path parameter is required'
    }),

  party_id: ciString(3).required()
    .messages({
      'any.required': 'party_id path parameter is required'
    }),

  session_id: ciString(36).required()
    .messages({
      'any.required': 'session_id path parameter is required'
    })
});

/**
 * Validates Session PUT request
 * @param {Object} params - Path parameters {country_code, party_id, session_id}
 * @param {Object} body - Request body (Session object)
 * @returns {Object} { valid: boolean, errors: Array, value: Object }
 */
function validateSessionPut(params, body) {
  // Validate path parameters
  const pathValidation = sessionPutPathSchema.validate(params, {
    abortEarly: false,
    stripUnknown: false
  });

  if (pathValidation.error) {
    return {
      valid: false,
      errors: pathValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  // Validate body
  const bodyValidation = sessionPutBodySchema.validate(body, {
    abortEarly: false,
    stripUnknown: true // Remove unknown fields to comply with OCPI spec
  });

  if (bodyValidation.error) {
    return {
      valid: false,
      errors: bodyValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  // Validate that path params match body values
  const pathParams = pathValidation.value;
  const bodyData = bodyValidation.value;

  const matchErrors = [];

  if (pathParams.country_code.toUpperCase() !== bodyData.country_code.toUpperCase()) {
    matchErrors.push({
      field: 'country_code',
      message: `country_code in path (${pathParams.country_code}) does not match body (${bodyData.country_code})`,
      type: 'mismatch'
    });
  }

  if (pathParams.party_id.toUpperCase() !== bodyData.party_id.toUpperCase()) {
    matchErrors.push({
      field: 'party_id',
      message: `party_id in path (${pathParams.party_id}) does not match body (${bodyData.party_id})`,
      type: 'mismatch'
    });
  }

  if (pathParams.session_id.toUpperCase() !== bodyData.id.toUpperCase()) {
    matchErrors.push({
      field: 'id',
      message: `session_id in path (${pathParams.session_id}) does not match body id (${bodyData.id})`,
      type: 'mismatch'
    });
  }

  if (matchErrors.length > 0) {
    return {
      valid: false,
      errors: matchErrors,
      value: null
    };
  }

  return {
    valid: true,
    errors: [],
    value: bodyData
  };
}

/**
 * Express middleware for Session PUT validation
 */
async function validateSessionPutMiddleware(req, res, next) {
  const validation = validateSessionPut(req.params, req.body);

  if (!validation.valid) {
    const errorMessage = validation.errors
      .map(err => `${err.field}: ${err.message}`)
      .join('; ');

    const logger = require('../utils/logger');
    logger.error('❌ Session PUT validation failed', {
      errors: validation.errors,
      body: req.body
    });

    // Log validation error to database
    const { logValidationError } = require('../utils/validationErrorLogger');
    await logValidationError({
      endpoint: req.originalUrl || req.url,
      method: req.method,
      requestBody: req.body,
      validationErrors: validation.errors,
      req
    });

    return res.status(400).json({
      status_code: 2001,
      status_message: `Invalid Session data: ${errorMessage}`,
      timestamp: new Date().toISOString(),
      errors: validation.errors
    });
  }

  // Store validated data in request for use in route handler
  req.validatedSession = validation.value;
  next();
}

/**
 * Session PATCH body validator (all fields optional except last_updated)
 * Allows partial updates according to OCPI 2.2 spec
 * Note: OCPI 2.2 requires last_updated in ALL PATCH requests
 */
const sessionPatchBodySchema = Joi.object({
  country_code: ciString(2).optional(),
  party_id: ciString(3).optional(),
  id: ciString(36).optional(),
  start_date_time: dateTime().optional(),
  end_date_time: dateTime().optional(),
  kwh: ocpiNumber().optional(),
  cdr_token: cdrTokenSchema.optional(),
  auth_method: Joi.string().valid(...AUTH_METHODS).optional(),
  authorization_reference: ciString(36).optional(),
  location_id: ciString(36).optional(),
  evse_uid: ciString(36).optional(),
  connector_id: ciString(36).optional(),
  meter_id: ocpiString(255).optional(),
  currency: Joi.string().length(3).uppercase().optional(),
  charging_periods: Joi.array().items(chargingPeriodSchema).optional(),
  total_cost: priceSchema.optional(),
  status: Joi.string().valid(...SESSION_STATUSES).optional(),
  last_updated: dateTime().required()
    .messages({
      'any.required': 'last_updated is required in PATCH requests (OCPI 2.2 specification)',
      'string.isoDate': 'last_updated must be a valid ISO 8601 datetime'
    })
}).min(2) // At least last_updated + 1 other field
  .messages({
    'object.min': 'PATCH request must include at least one field to update besides last_updated'
  });

/**
 * Validates Session PATCH request
 * @param {Object} params - Path parameters {country_code, party_id, session_id}
 * @param {Object} body - Request body (partial Session object)
 * @returns {Object} { valid: boolean, errors: Array, value: Object }
 */
function validateSessionPatch(params, body) {
  // Validate path parameters
  const pathValidation = sessionPutPathSchema.validate(params, {
    abortEarly: false,
    stripUnknown: false
  });

  if (pathValidation.error) {
    return {
      valid: false,
      errors: pathValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  // Validate body
  const bodyValidation = sessionPatchBodySchema.validate(body, {
    abortEarly: false,
    stripUnknown: true
  });

  if (bodyValidation.error) {
    return {
      valid: false,
      errors: bodyValidation.error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message,
        type: detail.type
      })),
      value: null
    };
  }

  // Validate that path params match body values (if provided in body)
  const pathParams = pathValidation.value;
  const bodyData = bodyValidation.value;

  const matchErrors = [];

  if (bodyData.country_code && pathParams.country_code.toUpperCase() !== bodyData.country_code.toUpperCase()) {
    matchErrors.push({
      field: 'country_code',
      message: `country_code in path (${pathParams.country_code}) does not match body (${bodyData.country_code})`,
      type: 'mismatch'
    });
  }

  if (bodyData.party_id && pathParams.party_id.toUpperCase() !== bodyData.party_id.toUpperCase()) {
    matchErrors.push({
      field: 'party_id',
      message: `party_id in path (${pathParams.party_id}) does not match body (${bodyData.party_id})`,
      type: 'mismatch'
    });
  }

  if (bodyData.id && pathParams.session_id.toUpperCase() !== bodyData.id.toUpperCase()) {
    matchErrors.push({
      field: 'id',
      message: `session_id in path (${pathParams.session_id}) does not match body id (${bodyData.id})`,
      type: 'mismatch'
    });
  }

  if (matchErrors.length > 0) {
    return {
      valid: false,
      errors: matchErrors,
      value: null
    };
  }

  return {
    valid: true,
    errors: [],
    value: bodyData
  };
}

/**
 * Express middleware for Session PATCH validation
 */
async function validateSessionPatchMiddleware(req, res, next) {
  const validation = validateSessionPatch(req.params, req.body);

  if (!validation.valid) {
    const errorMessage = validation.errors
      .map(err => `${err.field}: ${err.message}`)
      .join('; ');

    const logger = require('../utils/logger');
    logger.error('❌ Session PATCH validation failed', {
      errors: validation.errors,
      body: req.body
    });

    // Log validation error to database
    const { logValidationError } = require('../utils/validationErrorLogger');
    await logValidationError({
      endpoint: req.originalUrl || req.url,
      method: req.method,
      requestBody: req.body,
      validationErrors: validation.errors,
      req
    });

    return res.status(400).json({
      status_code: 2001,
      status_message: `Invalid Session PATCH data: ${errorMessage}`,
      timestamp: new Date().toISOString(),
      errors: validation.errors
    });
  }

  // Store validated data in request for use in route handler
  req.validatedSessionPatch = validation.value;
  next();
}

module.exports = {
  sessionPutBodySchema,
  sessionPutPathSchema,
  sessionPatchBodySchema,
  cdrTokenSchema,
  priceSchema,
  chargingPeriodSchema,
  validateSessionPut,
  validateSessionPutMiddleware,
  validateSessionPatch,
  validateSessionPatchMiddleware,
  TOKEN_TYPES,
  AUTH_METHODS,
  SESSION_STATUSES
};

