/**
 * OCPI 2.2 Tariff Validators
 * According to OCPI 2.2 specification - Tariffs Module
 * 
 * Este archivo re-exporta todos los esquemas y funciones de validación
 * desde módulos más pequeños para mantener compatibilidad con código existente.
 */

// Importar enums
const enums = require('./tariffValidators/enums');

// Importar esquemas básicos
const basicSchemas = require('./tariffValidators/basicSchemas');

// Importar esquemas de tarifas
const tariffSchemas = require('./tariffValidators/tariffSchemas');

// Importar esquemas de energía
const energySchemas = require('./tariffValidators/energySchemas');

// Importar esquemas de Tariff body
const tariffBodySchemas = require('./tariffValidators/tariffBodySchemas');

// Importar funciones de validación
const validationFunctions = require('./tariffValidators/validationFunctions');

// Re-exportar todo para mantener compatibilidad
module.exports = {
  // Esquemas principales
  tariffPutBodySchema: tariffBodySchemas.tariffPutBodySchema,
  tariffPatchBodySchema: tariffBodySchemas.tariffPatchBodySchema,
  tariffPutPathSchema: tariffBodySchemas.tariffPutPathSchema,
  tariffElementSchema: tariffSchemas.tariffElementSchema,
  priceComponentSchema: tariffSchemas.priceComponentSchema,
  tariffRestrictionsSchema: tariffSchemas.tariffRestrictionsSchema,
  energyMixSchema: energySchemas.energyMixSchema,
  energySourceSchema: energySchemas.energySourceSchema,
  environmentalImpactSchema: energySchemas.environmentalImpactSchema,

  // Funciones de validación
  validateTariffPut: validationFunctions.validateTariffPut,
  validateTariffPutMiddleware: validationFunctions.validateTariffPutMiddleware,
  validateTariffPatch: validationFunctions.validateTariffPatch,
  validateTariffPatchMiddleware: validationFunctions.validateTariffPatchMiddleware,

  // Enums
  TARIFF_TYPES: enums.TARIFF_TYPES,
  TARIFF_DIMENSION_TYPES: enums.TARIFF_DIMENSION_TYPES,
  DAYS_OF_WEEK: enums.DAYS_OF_WEEK,
  RESERVATION_RESTRICTION_TYPES: enums.RESERVATION_RESTRICTION_TYPES,
  ENERGY_SOURCE_CATEGORIES: enums.ENERGY_SOURCE_CATEGORIES,
  ENVIRONMENTAL_IMPACT_CATEGORIES: enums.ENVIRONMENTAL_IMPACT_CATEGORIES
};

const Joi = require('joi');
const { ocpiString, ocpiNumber } = require('../../utils/ocpiValidators');

/**
 * Esquemas básicos para validadores Tariff
 */

/**
 * DisplayText schema validator
 * For multi-language text fields
 */
const displayTextSchema = Joi.object({
  language: Joi.string()
    .length(2)
    .lowercase()
    .required()
    .messages({
      'any.required': 'display_text.language is required',
      'string.length': 'display_text.language must be exactly 2 characters (ISO-639-1)'
    }),

  text: ocpiString(512).required()
    .messages({
      'any.required': 'display_text.text is required',
      'string.max': 'display_text.text must be at most 512 characters'
    })
}).messages({
  'object.base': 'display_text must be a valid object'
});

/**
 * Price schema validator (16.5)
 * Used for min_price and max_price
 */
const priceSchema = Joi.object({
  excl_vat: ocpiNumber().required()
    .messages({
      'any.required': 'price.excl_vat is required',
      'number.base': 'price.excl_vat must be a number'
    }),

  incl_vat: ocpiNumber().optional()
    .messages({
      'number.base': 'price.incl_vat must be a number'
    })
}).messages({
  'object.base': 'price must be a valid Price object'
});

module.exports = {
  displayTextSchema,
  priceSchema
};

const Joi = require('joi');
const { ocpiString, ocpiNumber } = require('../../utils/ocpiValidators');
const {
  ENERGY_SOURCE_CATEGORIES,
  ENVIRONMENTAL_IMPACT_CATEGORIES
} = require('./enums');

/**
 * Esquemas relacionados con energía para validadores Tariff
 */

/**
 * EnergySource schema validator (8.4.7)
 */
const energySourceSchema = Joi.object({
  source: Joi.string()
    .valid(...ENERGY_SOURCE_CATEGORIES)
    .required()
    .messages({
      'any.required': 'energy_source.source is required'
    }),

  percentage: ocpiNumber()
    .min(0)
    .max(100)
    .required()
    .messages({
      'any.required': 'energy_source.percentage is required',
      'number.base': 'energy_source.percentage must be a number',
      'number.min': 'energy_source.percentage must be at least 0',
      'number.max': 'energy_source.percentage must be at most 100'
    })
}).messages({
  'object.base': 'energy_source must be a valid object'
});

/**
 * EnvironmentalImpact schema validator (8.4.9)
 */
const environmentalImpactSchema = Joi.object({
  category: Joi.string()
    .valid(...ENVIRONMENTAL_IMPACT_CATEGORIES)
    .required()
    .messages({
      'any.required': 'environmental_impact.category is required'
    }),

  amount: ocpiNumber().required()
    .messages({
      'any.required': 'environmental_impact.amount is required',
      'number.base': 'environmental_impact.amount must be a number'
    })
}).messages({
  'object.base': 'environmental_impact must be a valid object'
});

/**
 * EnergyMix schema validator (8.4.6)
 */
const energyMixSchema = Joi.object({
  is_green_energy: Joi.boolean().required()
    .messages({
      'any.required': 'energy_mix.is_green_energy is required',
      'boolean.base': 'energy_mix.is_green_energy must be a boolean'
    }),

  energy_sources: Joi.array()
    .items(energySourceSchema)
    .optional()
    .messages({
      'array.base': 'energy_mix.energy_sources must be an array'
    }),

  environ_impact: Joi.array()
    .items(environmentalImpactSchema)
    .optional()
    .messages({
      'array.base': 'energy_mix.environ_impact must be an array'
    }),

  supplier_name: ocpiString(64).optional()
    .messages({
      'string.max': 'energy_mix.supplier_name must be at most 64 characters'
    }),

  energy_product_name: ocpiString(64).optional()
    .messages({
      'string.max': 'energy_mix.energy_product_name must be at most 64 characters'
    })
}).messages({
  'object.base': 'energy_mix must be a valid object'
});

module.exports = {
  energySourceSchema,
  environmentalImpactSchema,
  energyMixSchema
};

